referenceSolutionTemplate:
public class Main {
    static int 查了几项 = 0;
    static int 红了几项 = 0;

    static void 查接近(String 名字, double 叼回来, double 该是) {
        查了几项++;
        if (Math.abs(叼回来 - 该是) < 1e-9) {
            System.out.println("绿 " + 名字);
        } else {
            红了几项++;
            System.out.println("红 " + 名字 + "：叼回来 " + 叼回来 + "，该是 " + 该是);
        }
    }

    public static void main(String[] args) {
        查接近("{l1}", 0.1 + 0.2, 0.3);
        查接近("{l2}", 1.0, 2.0);
        查接近("{l3}", 0.25 + 0.25, 0.5);
        System.out.println("体检了 " + 查了几项 + " 项，红了 " + 红了几项 + " 项");
    }
}
